#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    int best = 0, i = 1;
    while (i < n - 1) {
        if (a[i - 1] < a[i] && a[i] > a[i + 1]) {
            int l = i - 1;
            while (l > 0 && a[l - 1] < a[l]) l--;
            int rr = i + 1;
            while (rr < n - 1 && a[rr] > a[rr + 1]) rr++;
            best = max(best, rr - l + 1);
            i = rr;
        } else {
            i++;
        }
    }
    cout << best << "\n";

    return 0;
}

